from p4common import *
LS=lambda id: json.load(open(os.path.join(ROOT,'lessons',id+'.json')))['sources']
def Q(id,task,stem,right,rexp,wrongs,kw,point,les,svs=[],extra=[],fmt="scenario"):
    return SQ(id,task,"standard",stem,right,rexp,wrongs,kw,point,LS(les),[L(les)]+extra,svs,fmt)
def MQ(id,task,stem,rights,wrongs,kw,point,les,svs=[]):
    ch=[(t,True,e,None) for t,e in rights]+[(t,False,e,el) for t,e,el in wrongs]
    d=q(id,"saa-d"+task[4],task,"scenario","multiple","standard",stem,ch,kw,point,LS(les),svs,[L(les)],None,None)
    d['exam']='saa'; d['basedOnGuide']=GS
    for c in d['choices']:
        assert len(c['explanation'])>=20,(id,c['text'])
        if not c['correct']: assert c['eliminatedBy'] in stem,(id,c['eliminatedBy'])
    for k in kw: assert k in stem,(id,k)
    assert len(ch)==5 and len({c[0] for c in ch})==5
    return d
A1="saa-secure-access"; A2="saa-secure-workloads"; A3="saa-data-security"; B1="saa-scalable-loose"; B2="saa-ha-ft"
CS="saa-cost-storage"; CD="saa-cost-database"; PD="saa-perf-database"

